function report = buildBenchmarkTools(options)
%BUILDBENCHMARKTOOLS Build and verify all project-owned native kernels.
%   REPORT = BUILDBENCHMARKTOOLS() builds the fixed-source and scheduled
%   C++ MEX kernels in dependency order. Every builder verifies source and
%   binary hashes and runs its numerical parity gate before promotion.
%
%   REPORT = BUILDBENCHMARKTOOLS(Action="check") performs a read-only
%   environment and active-cache check without compiling code.
%
%   Generated files are placed in release-, architecture-, and source-hash
%   specific cache folders. SHARPy and XBeam are external dependencies and
%   are never modified by this function.

arguments
    options.Action (1,1) string ...
        {mustBeMember(options.Action,["build","check"])} = "build"
    options.Force (1,1) logical = false
    options.RunParity (1,1) logical = true
    options.TimingRepetitions (1,1) double ...
        {mustBeInteger,mustBePositive} = 3
    options.ProjectInfo (1,1) struct = struct()
end

if isempty(fieldnames(options.ProjectInfo))
    project = setupProject(ValidateEntryPoints=true);
else
    project = options.ProjectInfo;
end
environment = localEnvironment(project);

% The report is returned even when a later component fails. This makes a
% partial toolchain installation diagnosable without losing earlier results.
report = struct( ...
    "schemaVersion","pazy-native-tool-build-v1", ...
    "action",options.Action, ...
    "startedUtc",localUtcNow(), ...
    "endedUtc","", ...
    "passed",false, ...
    "environment",environment, ...
    "components",struct.empty(0,1), ...
    "fallback",struct( ...
        "fixedSource","exact MATLAB reciprocal provider", ...
        "scheduled","exact MATLAB scheduled reciprocal model bank"), ...
    "externalDependencies",struct( ...
        "sharpy","immutable; not built here", ...
        "xbeam","immutable; not built here"));

if options.Action=="check"
    report.components = localActiveComponents(project);
    report.passed = environment.releaseSupported && ...
        environment.architectureSupported && ...
        all([report.components.active]);
    report.endedUtc = localUtcNow();
    localPrintSummary(report);
    return
end

assert(environment.matlabCoderAvailable, ...
    "AeroFlex:BuildToolsMatlabCoder", ...
    ["MATLAB Coder is required to build the optional native kernels. ", ...
     "The exact MATLAB implementations remain available."]);
assert(environment.cppCompilerSelected, ...
    "AeroFlex:BuildToolsCompiler", ...
    ["No supported C++ compiler is selected. Run 'mex -setup C++', ", ...
     "then rerun buildBenchmarkTools."]);

builders = [ ...
    struct("name","fixed_interval", ...
        "function","buildPhase18CompiledControlKernels"); ...
    struct("name","scheduled_interval", ...
        "function","buildPhase18ScheduledCompiledControlKernel"); ...
    struct("name","scheduled_horizon", ...
        "function","buildPhase18ScheduledCompiledHorizonKernels"); ...
    struct("name","scheduled_value_horizon", ...
        "function","buildPhase18ScheduledCompiledValueHorizonKernels"); ...
    struct("name","scheduled_causal_rollout", ...
        "function","buildPhase18ScheduledCompiledCausalRolloutKernels")];
componentCells = cell(numel(builders),1);

% Continue through the complete build order so users receive one actionable
% report instead of fixing one missing binary per invocation.
for index = 1:numel(builders)
    entry = builders(index);
    fprintf("Building %-28s with %s ...\n",entry.name,entry.function);
    timer = tic;
    try
        switch entry.name
            case {"fixed_interval","scheduled_interval"}
                details = feval(entry.function,Force=options.Force, ...
                    RunParity=options.RunParity);
            case "scheduled_horizon"
                details = feval(entry.function,Force=options.Force, ...
                    RunParity=options.RunParity, ...
                    TimingRepetitions=options.TimingRepetitions);
            otherwise
                details = feval(entry.function,Force=options.Force, ...
                    TimingRepetitions=options.TimingRepetitions);
        end
        componentCells{index} = struct( ...
            "name",entry.name,"builder",entry.function, ...
            "passed",logical(details.passed), ...
            "elapsedSeconds",toc(timer), ...
            "details",details,"error",struct());
    catch exception
        componentCells{index} = struct( ...
            "name",entry.name,"builder",entry.function, ...
            "passed",false,"elapsedSeconds",toc(timer), ...
            "details",struct(),"error",struct( ...
                "identifier",string(exception.identifier), ...
                "message",string(exception.message)));
        fprintf(2,"Build failed for %s: %s\n", ...
            entry.name,exception.message);
    end
end
report.components = vertcat(componentCells{:});
report.passed = all([report.components.passed]);
report.endedUtc = localUtcNow();
localPrintSummary(report);
if ~report.passed
    error('AeroFlex:BuildToolsFailed', ...
        ['One or more native components failed to build or pass parity. ', ...
         'Inspect report.components; exact MATLAB fallbacks remain available.']);
end
end

function environment = localEnvironment(project)
releaseName = string(version("-release"));
architecture = string(computer("arch"));
compiler = mex.getCompilerConfigurations("C++","Selected");
environment = struct( ...
    "matlabRelease",releaseName, ...
    "matlabVersion",string(version), ...
    "architecture",architecture, ...
    "mexExtension",string(mexext), ...
    "releaseSupported",releaseName=="2025b", ...
    "architectureSupported",architecture=="win64", ...
    "matlabCoderAvailable",~isempty(which("coder.config")), ...
    "cppCompilerSelected",~isempty(compiler), ...
    "compiler",struct("name","","version","","location",""), ...
    "repositoryRoot",string(project.repositoryRoot));
if ~isempty(compiler)
    environment.compiler = struct( ...
        "name",string(compiler.Name), ...
        "version",string(compiler.Version), ...
        "location",string(compiler.Location));
end
end

function components = localActiveComponents(project)
baseComponents = [ ...
    struct("name","fixed_interval", ...
        "active",logical(project.compiledControl.active), ...
        "path",string(project.compiledControl.path), ...
        "message",string(project.compiledControl.message)); ...
    struct("name","scheduled_interval", ...
        "active",logical(project.scheduledCompiledControl.active), ...
        "path",string(project.scheduledCompiledControl.path), ...
        "message",string(project.scheduledCompiledControl.message))];
root = fullfile(project.repositoryRoot,"MatlabFlex","cache");
specifications = [ ...
    struct("name","scheduled_horizon", ...
        "folder","compiled_control_scheduled_horizon", ...
        "manifest","PHASE18_SCHEDULED_COMPILED_HORIZON_MANIFEST.json"); ...
    struct("name","scheduled_value_horizon", ...
        "folder","compiled_control_scheduled_value_horizon", ...
        "manifest", ...
            "PHASE18_SCHEDULED_COMPILED_VALUE_HORIZON_MANIFEST.json"); ...
    struct("name","scheduled_causal_rollout", ...
        "folder","compiled_control_scheduled_causal_rollout", ...
        "manifest", ...
            "PHASE18_SCHEDULED_COMPILED_CAUSAL_ROLLOUT_MANIFEST.json")];
extra = repmat(struct("name","","active",false,"path","", ...
    "message","BUILD REQUIRED"),numel(specifications),1);
for index = 1:numel(specifications)
    specification = specifications(index);
    searchRoot = fullfile(root,specification.folder, ...
        version("-release"),computer("arch"));
    manifests = dir(fullfile(searchRoot,"**",specification.manifest));
    extra(index).name = specification.name;
    for manifestIndex = numel(manifests):-1:1
        manifestPath = fullfile(manifests(manifestIndex).folder, ...
            manifests(manifestIndex).name);
        try
            manifest = jsondecode(fileread(manifestPath));
            if localManifestBinariesPass(manifest, ...
                    manifests(manifestIndex).folder,project.repositoryRoot)
                extra(index).active = true;
                extra(index).path = string(manifests(manifestIndex).folder);
                extra(index).message = "ACTIVE (verified local MEX cache)";
                break
            end
        catch
            % An incomplete cache is ignored; the next candidate is checked.
        end
    end
end
components = [baseComponents;extra];
end

function passed = localManifestBinariesPass(manifest,folder,repositoryRoot)
passed = isfield(manifest,"passed") && logical(manifest.passed) && ...
    isfield(manifest,"matlabRelease") && ...
    string(manifest.matlabRelease)==string(version("-release")) && ...
    isfield(manifest,"architecture") && ...
    string(manifest.architecture)==string(computer("arch")) && ...
    isfield(manifest,"mexExtension") && ...
    string(manifest.mexExtension)==string(mexext) && ...
    isfield(manifest,"entries");
if ~passed, return, end
if ~isfield(manifest,"sourceFiles") || isempty(manifest.sourceFiles)
    passed = false;
    return
end
for source = reshape(manifest.sourceFiles,1,[])
    sourcePath = fullfile(repositoryRoot,string(source.path));
    passed = passed && isfile(sourcePath) && ...
        isfield(source,"sha256") && ...
        string(source.sha256)==localFileHash(sourcePath);
    if ~passed, return, end
end
entries = manifest.entries;
for index = 1:numel(entries)
    binary = fullfile(folder,char(string(entries(index).functionName) + ...
        "." + string(mexext)));
    passed = passed && logical(entries(index).passed) && isfile(binary) && ...
        string(entries(index).binarySha256)==localFileHash(binary);
    if ~passed, return, end
end
end

function value = localFileHash(path)
file = fopen(path,"rb");
assert(file>=0,"AeroFlex:BuildToolsHashRead", ...
    "Cannot read %s for hashing.",path);
cleanup = onCleanup(@()fclose(file));
engine = java.security.MessageDigest.getInstance("SHA-256");
while ~feof(file)
    bytes = fread(file,1024*1024,"*uint8");
    if isempty(bytes), break, end
    engine.update(bytes);
end
value = lower(string(sprintf("%02x",typecast( ...
    engine.digest(),"uint8"))));
clear cleanup
end

function localPrintSummary(report)
fprintf("\nPazy native-tool %s summary\n",report.action);
fprintf("  MATLAB       : %s (%s)\n", ...
    report.environment.matlabRelease,report.environment.architecture);
fprintf("  MATLAB Coder : %s\n",localYesNo( ...
    report.environment.matlabCoderAvailable));
fprintf("  C++ compiler : %s\n",localYesNo( ...
    report.environment.cppCompilerSelected));
for component = reshape(report.components,1,[])
    if isfield(component,"passed")
        state = component.passed;
    else
        state = component.active;
    end
    fprintf("  %-28s : %s\n",component.name,localPassFail(state));
end
fprintf("  Overall      : %s\n\n",localPassFail(report.passed));
end

function value = localYesNo(flag)
if flag, value = "yes"; else, value = "no"; end
end

function value = localPassFail(flag)
if flag, value = "PASS"; else, value = "NOT READY"; end
end

function value = localUtcNow()
value = string(datetime("now","TimeZone","UTC", ...
    "Format","yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"));
end
